{
  "root": "main_stack",
  "state": {
    "monthlyRevenueExpenses": [
      {
        "Month": "Jul 2023",
        "Revenue": 150000,
        "Expenses": 80000
      },
      {
        "Month": "Aug 2023",
        "Revenue": 165000,
        "Expenses": 85000
      },
      {
        "Month": "Sep 2023",
        "Revenue": 172000,
        "Expenses": 88000
      }
    ],
    "monthlyProfitMargin": [
      {
        "Month": "Jul 2023",
        "Profit Margin": 46.0
      },
      {
        "Month": "Aug 2023",
        "Profit Margin": 48.0
      },
      {
        "Month": "Sep 2023",
        "Profit Margin": 49.0
      }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "padding": 16
      },
      "children": [
        "title_stack",
        "summary_card",
        "kpi_section",
        "revenue_expenses_section",
        "profit_margin_section"
      ]
    },
    "title_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "title_icon",
        "main_title"
      ]
    },
    "title_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000576_01_1_wallet-fill.svg"
      },
      "children": []
    },
    "main_title": {
      "type": "Text",
      "props": {
        "text": "Q3 2023 Financial Performance Dashboard",
        "variant": "h1"
      },
      "children": []
    },
    "summary_card": {
      "type": "Card",
      "props": {},
      "children": [
        "summary_text_stack"
      ]
    },
    "summary_text_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "summary_intro_text",
        "total_revenue_text",
        "profit_margin_text"
      ]
    },
    "summary_intro_text": {
      "type": "Text",
      "props": {
        "text": "This dashboard provides a snapshot of your financial performance for Quarter 3 (July-September) of 2023."
      },
      "children": []
    },
    "total_revenue_text": {
      "type": "Text",
      "props": {
        "text": "Total revenue: $487,000"
      },
      "children": []
    },
    "profit_margin_text": {
      "type": "Text",
      "props": {
        "text": "Average profit margin: 48.05% for the quarter."
      },
      "children": []
    },
    "kpi_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "kpi_heading_stack",
        "kpi_card"
      ]
    },
    "kpi_heading_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "kpi_icon",
        "kpi_title"
      ]
    },
    "kpi_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000576_01_2_graph-up.svg"
      },
      "children": []
    },
    "kpi_title": {
      "type": "Text",
      "props": {
        "text": "Key Performance Indicators",
        "variant": "h2"
      },
      "children": []
    },
    "kpi_card": {
      "type": "Card",
      "props": {},
      "children": [
        "kpi_list_stack"
      ]
    },
    "kpi_list_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "cac_text",
        "highest_revenue_text"
      ]
    },
    "cac_text": {
      "type": "Text",
      "props": {
        "text": "Average Customer Acquisition Cost (Q3): $47.67"
      },
      "children": []
    },
    "highest_revenue_text": {
      "type": "Text",
      "props": {
        "text": "Highest Monthly Revenue: $172,000 (September 2023)"
      },
      "children": []
    },
    "revenue_expenses_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "revenue_expenses_heading_stack",
        "revenue_expenses_description",
        "revenue_expenses_table"
      ]
    },
    "revenue_expenses_heading_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "revenue_expenses_icon",
        "revenue_expenses_title"
      ]
    },
    "revenue_expenses_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000576_01_3_graph-up-arrow.svg"
      },
      "children": []
    },
    "revenue_expenses_title": {
      "type": "Text",
      "props": {
        "text": "Monthly Revenue and Expenses Trend",
        "variant": "h2"
      },
      "children": []
    },
    "revenue_expenses_description": {
      "type": "Text",
      "props": {
        "text": "This data represents monthly revenue and expenses, showing trends over time."
      },
      "children": []
    },
    "revenue_expenses_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "Month",
            "label": "Month"
          },
          {
            "key": "Revenue",
            "label": "Revenue"
          },
          {
            "key": "Expenses",
            "label": "Expenses"
          }
        ],
        "statePath": "/monthlyRevenueExpenses",
        "domain": "status",
        "preferredPresentation": "cards",
        "primaryColumn": "Month",
        "highlightColumns": [
          "Revenue",
          "Expenses"
        ],
        "numericColumns": [
          "Revenue",
          "Expenses"
        ]
      },
      "children": []
    },
    "profit_margin_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "profit_margin_heading_stack",
        "profit_margin_description",
        "profit_margin_table"
      ]
    },
    "profit_margin_heading_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "profit_margin_icon",
        "profit_margin_title"
      ]
    },
    "profit_margin_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000576_01_4_bar-chart-line.svg"
      },
      "children": []
    },
    "profit_margin_title": {
      "type": "Text",
      "props": {
        "text": "Monthly Profit Margin",
        "variant": "h2"
      },
      "children": []
    },
    "profit_margin_description": {
      "type": "Text",
      "props": {
        "text": "This data showcases the profit margin for each month."
      },
      "children": []
    },
    "profit_margin_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "Month",
            "label": "Month"
          },
          {
            "key": "Profit Margin",
            "label": "Profit Margin"
          }
        ],
        "statePath": "/monthlyProfitMargin",
        "domain": "status",
        "preferredPresentation": "cards",
        "primaryColumn": "Month",
        "highlightColumns": [
          "Profit Margin"
        ],
        "numericColumns": [
          "Profit Margin"
        ]
      },
      "children": []
    }
  }
}
